  "course_robotics_mod_0_title": "Module 1 - Foundations ",
  "course_robotics_mod_0_topic_0": "1. Mathematics for Robotics: Comprehensive mathematical framework covering Algebra (Linear equations, Matrices, Vectors, Systems of equations), Calculus (Derivatives, Integrals, Partial derivatives), and Trigonometry (sin, cos, tan, Unit circle, Rotation).",
  "course_robotics_mod_0_topic_1": "Probability & Statistics for handling random variables, featuring Gaussian distribution, Bayes theorem, and Noise filtering.",
  "course_robotics_mod_0_topic_2": "Linear Algebra (Highly Important): Deep dive into matrix operations for coordinate transformations, including Matrix multiplication, Eigenvectors, Transformations, and Rotation matrices.",
  "course_robotics_mod_0_topic_3": "2. Physics for Robotics: Core physical principles governing system motions: Newton laws, Force & torque, Velocity & acceleration, Momentum, Friction, along with Electricity basics and Motors physics.",

  "course_robotics_mod_1_title": "Module 2 - Programming Fundamentals ",
  "course_robotics_mod_1_topic_0": "3. C Programming: Low-level programming fundamentals for microcontrollers, covering Variables, Loops, Functions, Arrays, Pointers, Structs, and Memory management.",
  "course_robotics_mod_1_topic_1": "Practical development of foundational firmware projects: Calculator, Sensor simulator, and UART communication.",
  "course_robotics_mod_1_topic_2": "4. Python for Robotics: Core syntax and object-oriented programming (Python basics, OOP), along with specialized engineering libraries including NumPy and Matplotlib.",
  "course_robotics_mod_1_topic_3": "Essential computer vision operations via OpenCV basics and implementation of hands-on projects: Camera processing, Object tracking, and Robot simulator.",

  "course_robotics_mod_2_title": "Module 3 - Electronics & Hardware ",
  "course_robotics_mod_2_topic_0": "5. Electronics Fundamentals: Circuit components including Voltage/current, Resistors, Capacitors, Transistors, MOSFET, Power systems architecture, and practical usage of the formula V = IR (Ohm's law).",
  "course_robotics_mod_2_topic_1": "6. Digital Logic Design: Digital system architectures featuring Binary system, Logic gates, Flip-flops, Finite State Machine (FSM) design, Registers, and Signal Timing.",
  "course_robotics_mod_2_topic_2": "Implementation of hardware control projects: Traffic light FSM and Digital counter.",
  "course_robotics_mod_2_topic_3": "7. Microcontroller Fundamentals: Development with specialized hardware platforms (STM32, Arduino, ESP32) and peripheral interfaces: GPIO, UART, SPI, I2C, ADC, PWM, Timers, Interrupts, and DMA.",
  "course_robotics_mod_2_topic_4": "Hands-on integration of mechatronic hardware: Smart sensor node, Bluetooth robot, and Motor controller.",

  "course_robotics_mod_3_title": "Module 4 - Robotics Core ",
  "course_robotics_mod_3_topic_0": "8. Robotics Fundamentals: In-depth kinematic and dynamic analysis of robotic systems, including Degrees of freedom, Coordinate systems, Forward kinematics and Inverse kinematics for link positioning, Robot dynamics, and Motion planning utilizing the distance formula.",
  "course_robotics_mod_3_topic_1": "9. Control Systems: Feedback systems architecture, Stability evaluation, and Transfer functions analysis.",
  "course_robotics_mod_3_topic_2": "Advanced PID control implementation and tuning utilizing the continuous-time controller formula: u(t)=K_p e(t)+K_i\\int e(t)dt+K_d\\frac{de(t)}{dt}.",
  "course_robotics_mod_3_topic_3": "Deployment of core control algorithms in robotics projects: Self-balancing robot, Line follower, and Drone stabilization.",
  "course_robotics_mod_3_topic_4": "10. Sensors & Actuators: Complex measurement systems integration (Sensors: Ultrasonic, IMU, Gyroscope, Accelerometer, GPS, LIDAR, Encoders, Camera) and actuator drive technologies (Actuators: Servo motors, DC motors, Stepper motors, BLDC).",
  "course_robotics_mod_3_topic_5": "End-to-end integration of sensory-motor behaviors: Obstacle avoidance robot and Autonomous rover.",

  "course_robotics_mod_4_title": "Module 5 - Embedded Robotics Software",
  "course_robotics_mod_4_topic_0": "11. Embedded Systems: Real-time firmware engineering utilizing Real-Time Operating Systems (RTOS / FreeRTOS), Task Scheduling, Memory optimization, and Real-time systems paradigms.",
  "course_robotics_mod_4_topic_1": "12. ROS2 (Robot Operating System): Building robust robot architectures using ROS2 computational graphs: Nodes, Topics, Publishers/subscribers, and Services.",
  "course_robotics_mod_4_topic_2": "Configuring spatial coordinate transformations (TF2) and deploying the autonomous navigation stack (Navigation stack) for practical applications: Mapping robot and Autonomous navigation.",

  "course_robotics_mod_5_title": "Module 6 - AI & Computer Vision",
  "course_robotics_mod_5_topic_0": "13. Computer Vision: Utilizing the OpenCV library for advanced Image processing, Edge detection, Object detection, and exploring SLAM basics.",
  "course_robotics_mod_5_topic_1": "Developing vision-guided robotics projects: Face tracking robot and Object following robot.",
  "course_robotics_mod_5_topic_2": "14. AI for Robotics: Applying modern artificial intelligence: Neural networks, CNN, Reinforcement learning, and intelligent path planning algorithms (Path planning AI).",
  "course_robotics_mod_5_topic_3": "Hands-on development with industry-standard frameworks PyTorch and TensorFlow for projects: AI autonomous car and Vision-based robot.",

  "course_robotics_mod_6_title": "Module 7 - Advanced Robotics",
  "course_robotics_mod_6_topic_0": "15. Autonomous Systems: Advanced navigation stacks including comprehensive SLAM, state estimation via Localization, noise filtering with Kalman filter, Path planning, and Multi-agent systems coordination.",
  "course_robotics_mod_6_topic_1": "16. FPGA for Robotics: Specialized hardware track focusing on Verilog/SystemVerilog, FPGA architecture, Parallel processing, and Hardware acceleration.",
  "course_robotics_mod_6_topic_2": "Building high-performance hardware-accelerated applications: FPGA motor controller and Vision accelerator.",

  "course_robotics_mod_7_title": "Module 8 - Mechanical Robotics",
  "course_robotics_mod_7_topic_0": "17. Mechanical Design: 3D Computer-Aided Design (CAD) modeling inside Fusion 360 and SolidWorks environments.",
  "course_robotics_mod_7_topic_1": "Structural engineering of Robot arms, structural mobile layouts (Chassis design), and mechanical transmission selection (Gears).",

