  "course_mobile_outcome_2": "Ճարտարապետական մոդելների ներդրում (BLoC, Riverpod, Clean Architecture):",
  "course_mobile_outcome_3": "Ինտեգրում բեքենդների և ամպային ծառայությունների հետ (Firebase, REST APIs):",
  "course_mobile_outcome_4": "Աշխատանք տեղական տվյալների բազաների և քեշավորման մեխանիզմների հետ:",
  "course_mobile_outcome_5": "Հավելվածների հրապարակում Google Play-ում և App Store-ում:",

  "course_mobile_mod_0_title": "Մոդուլ 1 — Ծրագրավորման հիմունքներ + Dart",
  "course_mobile_mod_0_topic_0": "Ներածություն մոբայլ մշակման մեջ:",
  "course_mobile_mod_0_topic_1": "Dart լեզվի հիմունքները:",
  "course_mobile_mod_0_topic_2": "Ֆունկցիաներ և ՕՕԾ (Օբյեկտողնորոշված ծրագրավորում):",

