  "course_mobile_mod_2_title": "Մոդուլ 3 — Իրական հավելվածների մշակում",
  "course_mobile_mod_2_topic_0": "Մաքուր կոդ և ճարտարապետություն (Clean Code & Architecture):",
  "course_mobile_mod_2_topic_1": "BLoC մոդել:",
  "course_mobile_mod_2_topic_2": "Տվյալների մշտական պահպանում (Persistence):",

  "course_mobile_mod_3_title": "Մոդուլ 4 — APIs և Բեքենդ",
  "course_mobile_mod_3_topic_0": "Ասինխրոն ծրագրավորում:",
