"course_probability_stats_desc": "Համակարգչային ճարտարագիտության համապարփակ դասընթաց՝ կենտրոնացած պատահական մեծությունների, հավանականության բաշխումների, Բեյսյան ցանցերի և տվյալների վրա հիմնված վիճակագրական վարկածների գնահատման վրա։",

"course_probability_stats_outcome_0": "Խորությամբ հասկանալ դիսկրետ և անընդհատ պատահական մեծությունները",
"course_probability_stats_outcome_1": "Կիրառել հավանականության բաշխումները ցանցային երթևեկությունը և սերվերի ծանրաբեռնվածությունը մոդելավորելու համար",
"course_probability_stats_outcome_2": "Օգտագործել Առավելագույն հավանականության գնահատումը (MLE) վիճակագրական կանխատեսումների համար",
"course_probability_stats_outcome_3": "Նախագծել և ճշգրիտ մշակել ինժեներական և UI A/B թեստավորման շրջանակներ",

"course_probability_stats_mod_0_title": "Մոդուլ 1 — Սկզբունքներ և դասական հավանականություն",
"course_probability_stats_mod_0_topic_0": "Կոմբինատորիկա (տարբերակումներ և զուգորդություններ)",
"course_probability_stats_mod_0_topic_1": "Պատահական փորձեր և ելքեր",
"course_probability_stats_mod_0_topic_2": "Նմուշային տարածություններ",
"course_probability_stats_mod_0_topic_3": "Հավանականության դասական սահմանումը",
