"course_probability_stats_mod_1_title": "Մոդուլ 2 — Թեորեմներ և Բեյսյան տեսություն",
"course_probability_stats_mod_1_topic_0": "Հավանականության հատկություններ (հակադարձ իրադարձություններ, գումարման թեորեմ)",
"course_probability_stats_mod_1_topic_1": "Բազմապատկման թեորեմ",
"course_probability_stats_mod_1_topic_2": "Երկրաչափական հավանականություն",
"course_probability_stats_mod_1_topic_3": "Պայմանական հավանականություն, անկախ և կախյալ իրադարձություններ",
