"course_probability_stats_mod_2_title": "Մոդուլ 3 — Պատահական մեծություններ",
"course_probability_stats_mod_2_topic_0": "Դիսկրետ և շարունակական պատահական մեծություններ",
"course_probability_stats_mod_2_topic_1": "Հավանականության բաշխման օրենքներ",
"course_probability_stats_mod_2_topic_2": "Մաթեմատիկական սպասում",
"course_probability_stats_mod_2_topic_3": "Դիսպերսիա",
"course_probability_stats_mod_2_topic_4": "Ստանդարտ շեղում",

"course_probability_stats_mod_3_title": "Մոդուլ 4 — Բաշխումներ և ֆունկցիաներ",
"course_probability_stats_mod_3_topic_0": "Դիսկրետ բաշխումներ (հավասարաչափ, բինոմական, Պուասոնի, երկրաչափական, Պասկալի, հիպերերկրաչափական)",
"course_probability_stats_mod_3_topic_1": "Շարունակական բաշխումներ (շարունակական հավասարաչափ, նորմալ/Գաուսյան, էքսպոնենցյալ)",
"course_probability_stats_mod_3_topic_2": "Ֆունկցիաներ՝ PMF (Probability Mass Function)",
"course_probability_stats_mod_3_topic_3": "Ֆունկցիաներ՝ PDF (Probability Density Function)",
"course_probability_stats_mod_3_topic_4": "Ֆունկցիաներ՝ CDF (Cumulative Distribution Function)",
  "course_fpga_dur": "2 ամիս",
