"course_javascript_mod_0_topic_2": " 3. Կարնոյի քարտեր և ֆունկցիաների պարզեցում",
"course_javascript_mod_0_topic_3": " 4. Կոմբինացիոն տրամաբանության նախագծման սկզբունքները",
"course_javascript_mod_0_topic_4": " 5. Կոմբինացիոն տրամաբանության նախագծում MSI սխեմաներով",
"course_javascript_mod_0_topic_5": " 6. Տրիգերներ (Latches & Flip-Flops)",
"course_javascript_mod_0_topic_6": " 7. Հաշվիչներ և ռեգիստրներ",
"course_javascript_mod_0_topic_7": " 8. Հաջորդական սխեմաներ տակտային կառավարմամբ",
"course_javascript_mod_0_topic_8": " 9. Իրադարձություններով կառավարվող ասինխրոն սխեմաներ",
"course_javascript_mod_0_topic_9": " 10. Չափիչ սարքեր և միջերեսների համակցում",
"course_javascript_mod_0_topic_10": " 11. Ծրագրավորվող տրամաբանական սարքեր (PLD)",
