"course_javascript_mod_1_topic_0": "1. Փոփոխականներ և տվյալների տիպեր",
"course_javascript_mod_1_topic_1": "2. Օպերատորներ",
"course_javascript_mod_1_topic_2": "3. Մուտք և ելք",
"course_javascript_mod_1_topic_3": "4. Պայմանի օպերատորներ",
"course_javascript_mod_1_topic_4": "5. Ցիկլեր",
"course_javascript_mod_1_topic_5": "6. Ֆունկցիաներ",
"course_javascript_mod_1_topic_6": "7. Զանգվածներ",
"course_javascript_mod_1_topic_7": "8. Տողեր",
"course_javascript_mod_1_topic_8": "9. Ցուցիչներ",
"course_javascript_mod_1_topic_9": "10. Կառուցվածքներ և միավորումներ",
"course_javascript_mod_1_topic_10": "11. Հիշողության դինամիկ հատկացում",
