"course_javascript_mod_1_topic_14": "15. Տվյալների կառուցվածքները C լեզվով",

"course_javascript_mod_2_title": "Մոդուլ 3 — JavaScript Ճարտարագիտություն",
"course_javascript_mod_2_topic_0": "1. JavaScript ցածր մակարդակի տեսանկյունից",
"course_javascript_mod_2_topic_1": "2. JavaScript-ի ներքին կառուցվածքը (Internals)",
"course_javascript_mod_2_topic_2": "3. Ֆունկցիաները հիշողության մեջ",
"course_javascript_mod_2_topic_3": "4. Փոփոխականների որոնում և տեսանելիության տիրույթ (Scope)",
"course_javascript_mod_2_topic_4": "5. Փոփոխականների որոնում և փակումներ (Closures)",
"course_javascript_mod_2_topic_5": "6. Ֆունկցիոնալ ծրագրավորում",
"course_javascript_mod_2_topic_6": "7. JS-ի լեքսիկական կառուցվածքը",
"course_javascript_mod_2_topic_7": "8. Օբյեկտները բարձր մակարդակում",
"course_javascript_mod_2_topic_8": "9. V8 շարժիչի օպտիմալացումները",
"course_javascript_mod_2_topic_9": "10. Օբյեկտային կողմնորոշված նախագծման փիլիսոփայությունը",
"course_javascript_mod_2_topic_10": "11. Պոլիմորֆիզմ և կոնտեքստի կանչի մանրամասները",
"course_javascript_mod_2_topic_11": "12. Պրոտոտիպեր և [[Prototype]] հատկությունը",
"course_javascript_mod_2_topic_12": "13. Կոնստրուկտոր ֆունկցիաներ և ժառանգման ներքին մեխանիզմներ",
"course_javascript_mod_2_topic_13": "14. Աբստրակցիա և մետածրագրավորում",
"course_javascript_mod_2_topic_14": "15. SOLID սկզբունքները և օբյեկտային կողմնորոշված նախագծում",
"course_javascript_mod_2_topic_15": "16. Ստեղծող (Creational) նախագծման կաղապարներ",
"course_javascript_mod_2_topic_16": "17. Կառուցվածքային (Structural) նախագծման կաղապարներ",
"course_javascript_mod_2_topic_17": "18. Վարքագծային (Behavioral) նախագծման կաղապարներ",
"course_javascript_mod_2_topic_18": "19. Պրոցեսներ, թելեր և ասինխրոնություն",
"course_javascript_mod_2_topic_19": "20. Խորը սուզում ասինխրոնության մեջ (Deep Dive Async)",

"course_javascript_mod_3_title": "Մոդուլ 4 — Տվյալների կառուցվածքներ և ալգորիթմներ",
"course_javascript_mod_3_topic_0": "1. Ներածություն ալգորիթմների և տվյալների կառուցվածքների",
"course_javascript_mod_3_topic_1": "2-3. LeetCode խնդիրների լուծում (Երկու ցուցիչներ և խնդիրների լուծման այլ տեխնիկաներ)",
"course_javascript_mod_3_topic_2": "4. Տեղադրմամբ տեսակավորում (Insertion Sort) և հաշվարկով տեսակավորում (Counting Sort)",
"course_javascript_mod_3_topic_3": "5. Արագ տեսակավորում (Quick Sort) և միաձուլմամբ տեսակավորում (Merge Sort)",
"course_javascript_mod_3_topic_4": "6. Կույտեր և պրիորիտետային հերթեր (Սահող պատուհանի և Quick Select-ի կիրառմամբ)",
"course_javascript_mod_3_topic_5": "7. Կապակցված ցուցակներ (Linked Lists)",
"course_javascript_mod_3_topic_6": "8. Խնդիրների լուծում (SLL, QS, SW)",
"course_javascript_mod_3_topic_7": "9. Միակապ ցուցակ (Single Linked List)",
"course_javascript_mod_3_topic_8": "10. Երկկապ ցուցակ (Double Linked List)",
"course_javascript_mod_3_topic_9": "11. Հեշ-աղյուսակներ (Hash Tables)",
"course_javascript_mod_3_topic_10": "12. Երկուական որոնման ծառեր (BST)",
"course_javascript_mod_3_topic_11": "13. Երկուական որոնման ծառեր (Ջնջում, DFS, BFS)",
"course_javascript_mod_3_topic_12": "14. LeetCode խնդիրների լուծում (BFS, DFS)",
"course_javascript_mod_3_topic_13": "15. Ներածություն AVL ծառերի",
"course_javascript_mod_3_topic_14": "16. AVL ծառերի իրականացման մանրամասները",
"course_javascript_mod_3_topic_15": "17. Կարմիր-սև ծառեր (Ավելացում)",
"course_javascript_mod_3_topic_16": "18. Կարմիր-սև ծառեր (Ջնջում)",
"course_javascript_mod_3_topic_17": "19. Կարմիր-սև ծառեր (Delete Fixup)",
"course_javascript_mod_3_topic_18": "20. Գրաֆներ և Կանի ալգորիթմ (Տոպոլոգիական տեսակավորում)",
"course_javascript_mod_3_topic_19": "21. Դեյկստրա և Բելման-Ֆորդ (Կարճագույն ուղի)",
