      "about_p2": "Մեր ծրագրերը նախագծված են նմանակելու իրական ծրագրային ապահովման ճարտարագիտական միջավայրը՝ համատեղելով համակարգչային գիտության հիմունքները, ժամանակակից տեխնոլոգիաները և համատեղ նախագծերի ստեղծումը։",
