  "course_math_mod_0_topic_3": "Գծային հավասարումների և անհավասարումների համախմբեր",
  "course_math_mod_0_topic_4": "Մոդուլ պարունակող հավասարումներ և անհավասարումներ",
  "course_math_mod_0_topic_5": "Քառակուսային եռանդամ, հավասարումներ և Վիետի թեորեմ",
  "course_math_mod_0_topic_6": "Երկրորդ աստիճանի անհավասարումներ",
  "course_math_mod_0_topic_7": "Ֆունկցիաներ. հատկություններ, զրոներ և գրաֆիկներ",
  "course_math_mod_0_topic_8": "Ռացիոնալ հավասարումներ և անհավասարումներ",
  "course_math_mod_0_topic_9": "Ռացիոնալ հավասարումների համակարգեր և գրաֆիկական եղանակ",
  "course_math_mod_0_topic_10": "Թվային հաջորդականություններ և պրոգրեսիաներ",
  "course_math_mod_0_topic_11": "Տեքստային խնդիրներ և մաթեմատիկական մոդելավորում",

  "course_math_mod_1_title": "Մոդուլ 2: Երկրաչափություն",
  "course_math_mod_1_topic_0": "Եռանկյուններ. հատկություններ, միջնագծեր, կիսորդներ",
  "course_math_mod_1_topic_1": "Զուգահեռ ուղիղներ և հատողներ",
  "course_math_mod_1_topic_2": "Եռանկյան անկյուններ և ուղղանկյուն եռանկյան հատկություններ",
  "course_math_mod_1_topic_3": "Բազմանկյուններ, զուգահեռագծեր, սեղաններ",
  "course_math_mod_1_topic_4": "Շրջանագիծ. շոշափող, կենտրոնական և ներգծյալ անկյուններ",
  "course_math_mod_1_topic_5": "Բազմանկյան մակերես և Պյութագորասի թեորեմ",
  "course_math_mod_1_topic_6": "Կոորդինատներ և երկրաչափական պատկերների հավասարումներ",
  "course_math_mod_1_topic_7": "Վեկտորներ. գումարում և հանում",
  "course_math_mod_1_topic_8": "Վեկտորների վերածում և անկյուններ",
  "course_math_mod_1_topic_9": "Նման եռանկյուններ և կիրառություններ",
  "course_math_mod_1_topic_10": "Եռանկյունաչափություն. սինուս, կոսինուս, թեորեմներ",
  "course_math_mod_1_topic_11": "Շրջանագծի երկարություն, մակերես և սեկտորներ",

  "course_physics_outcome_0": "Շարժման, կինեմատիկայի և դինամիկայի հիմնարար օրենքների ըմբռնում",
  "course_physics_outcome_1": "Մեխանիկական աշխատանքի, հզորության և ճնշման հասկացությունների կիրառումը ֆիզիկական համակարգերում",
  "course_physics_outcome_2": "Մեխանիկական տատանումների, ալիքների և ձայնային երևույթների վերլուծություն",
  "course_physics_outcome_3": "Էլեկտրական շղթաների, էլեկտրամագնիսական դաշտերի և երկրաչափական օպտիկայի սկզբունքների տիրապետում",

